original_prompt:
{
  "meta": {
    "description": "Structured prompt for generating an isometric city diorama in a miniature 3D style, with weather and environment adaptive to the specified city.",
    "variable": "${City:San Francisco}"
  },
  "prompt_structure": {
    "perspective_and_format": {
      "view": "Isometric camera view",
      "format": "Miniature 3D diorama resting on a floating square base serving as the ground plinth.",
      "ratio": "16:9 (vertical phone)"
    },
    "art_style": {
      "medium": "High-detail 3D render",
      "texture_quality": "Realistic textures appropriate for the region's architecture (e.g., stone/brick, stucco/adobe, glass/steel).",
      "vibe": "Toy-like but highly sophisticated architectural model with tactile material qualities."
    },
    "environment_and_atmosphere": {
      "weather": "Typical climate and weather conditions associated with the specified city (e.g., overcast/rainy for London, bright/sunny/arid for Cairo, snowy for Moscow). Lighting matches the weather.",
      "ground": "Ground surface material typical for the city (e.g., asphalt, cobblestones, sand, dirt). Surface conditions reflect the weather (e.g., wet with reflections if rainy, dry and dusty if arid, snow-covered if winter).",
      "background": "Sky gradient and atmosphere matching the chosen weather, filling the upper frame."
    },
    "architectural_elements": {
      "housing": "Dense cluster of residential or commercial buildings reflecting the city's vernacular architecture style.",
      "landmarks": "Isometric miniature representations of iconic landmarks defining the city."
    },
    "props_and_details": {
      "street_level": "Miniature elements specific to the city's vibe (e.g., iconic vehicles like yellow cabs or red buses, specific vegetation like palm trees or deciduous trees, streetlights, signage).",
      "life": "Tiny, stylized figures dressed in clothing appropriate for the climate and culture."
    },
    "text_overlay": {
      "content": "${City:San Francisco}",
      "font_style": "White, sans-serif, bold, uppercase letters",
      "placement": "Centered floating at the very top of the frame."
    }
  }
}

vi_prompt:
{
  "meta": {
    "description": "Prompt có cấu trúc để tạo sa bàn thành phố dạng isometric theo phong cách 3D thu nhỏ, tự động thích ứng thời tiết và môi trường theo thành phố được chỉ định.",
    "variable": "${City:San Francisco}"
  },
  "prompt_structure": {
    "perspective_and_format": {
      "view": "Góc nhìn camera Isometric",
      "format": "Sa bàn 3D thu nhỏ đặt trên bệ đỡ hình vuông lơ lửng làm nền đất.",
      "ratio": "16:9 (màn hình dọc điện thoại)"
    },
    "art_style": {
      "medium": "Kết xuất 3D chi tiết cao",
      "texture_quality": "Vật liệu bề mặt chân thực đặc trưng cho kiến trúc khu vực (ví dụ: đá/gạch, vữa trát/đất nện, kính/thép).",
      "vibe": "Mô hình kiến trúc tinh xảo như món đồ chơi cao cấp với chất cảm vật liệu chạm vào được."
    },
    "environment_and_atmosphere": {
      "weather": "Khí hậu và điều kiện thời tiết điển hình gắn liền với thành phố đã chọn (ví dụ: âm u/mưa cho London, nắng gắt/khô hạn cho Cairo, tuyết rơi cho Moscow). Ánh sáng phù hợp với thời tiết.",
      "ground": "Vật liệu bề mặt đường đặc trưng của thành phố (ví dụ: nhựa đường, đá cuội lát đường, cát, đất). Tình trạng bề mặt phản ánh thời tiết (ví dụ: ướt sũng phản chiếu bóng nước nếu trời mưa, khô bụi nếu hạn hán, phủ tuyết trắng nếu mùa đông).",
      "background": "Dải màu bầu trời và bầu không khí hài hòa với thời tiết đã chọn, lấp đầy phần trên của khung hình."
    },
    "architectural_elements": {
      "housing": "Cụm nhà ở hoặc tòa nhà thương mại san sát phản ánh đúng phong cách kiến trúc bản địa của thành phố.",
      "landmarks": "Bản tái hiện thu nhỏ dạng isometric của các địa danh biểu tượng định hình thành phố."
    },
    "props_and_details": {
      "street_level": "Các chi tiết thu nhỏ đặc trưng cho nhịp sống thành phố (ví dụ: phương tiện biểu tượng như taxi vàng hoặc xe buýt hai tầng đỏ, thảm thực vật đặc thù như cây cọ hoặc cây rụng lá, đèn đường, biển báo giao thông).",
      "life": "Những con người cách điệu siêu nhỏ mặc trang phục phù hợp với khí hậu và nét văn hóa địa phương."
    },
    "text_overlay": {
      "content": "${City:San Francisco}",
      "font_style": "Chữ màu trắng, phông sans-serif không chân, in đậm, viết hoa toàn bộ",
      "placement": "Căn giữa trôi lơ lửng ở vị trí trên cùng của khung hình."
    }
  }
}
